import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createNode as _ } from '@/primitives';
import { createText as __ } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // --- Plane Geometry ---
  // Use aspect ratio based on provided image (512x320 → 1.6)
  const planeGeom = new PlaneGeometry(1.6, 1);
  const planeMat = new MeshBasicNodeMaterial({ color: 0xffffff });
  const planeMesh = new Mesh(planeGeom, planeMat);
  root.add(planeMesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // --- Text Content ---
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const palette = config.intent?.visualSpec?.colors ?? {};

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 42,
      color: palette.paper ?? '#e8ecf2',
      align: 'center',
    });

    // Position text slightly above the plane
    txt.position.set(0, 0.45, 0.01);
    root.add(txt);
  }

  // --- Cinematic Primitives (if any) ---
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const inst = ctx.primitives[prim.name](root, prim.params);
      primitiveInstances.push(inst);
    }
  }

  // --- UserData & Cleanup ---
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose geometry & material
    planeGeom.dispose();
    planeMat.dispose();
    if (planeMat.map) planeMat.map.dispose();

    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }

    // Kill any GSAP timelines (none created here but safeguard)
    gsap.globalTimeline.clear();
  };

  return root;
}
